∀ {a b : ℕ} {Cell : Type} {cellFintype : Fintype Cell} {Node : Type} {nodeFintype : Fintype Node}
  {cellForm : Cell → Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ} {cellNode : Cell → Node} {parent : Node → Option Node}
  {rank : Node → ℕ} {eliminated : Node → Finset (Fin a)} {front : Node → Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ}
  {root : Node} {globalForm : Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ} {Cell_1 : Type} {cellFintype_1 : Fintype Cell_1}
  {Node_1 : Type} {nodeFintype_1 : Fintype Node_1} {cellForm_1 : Cell_1 → Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ}
  {cellNode_1 : Cell_1 → Node_1} {parent_1 : Node_1 → Option Node_1} {rank_1 : Node_1 → ℕ}
  {eliminated_1 : Node_1 → Finset (Fin a)} {front_1 : Node_1 → Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ}
  {root_1 : Node_1} {globalForm_1 : Matrix (Fin a ⊕ Fin b) (Fin a ⊕ Fin b) ℝ},
  { Cell := Cell, cellFintype := cellFintype, Node := Node, nodeFintype := nodeFintype, cellForm := cellForm,
        cellNode := cellNode, parent := parent, rank := rank, eliminated := eliminated, front := front, root := root,
        globalForm := globalForm } =
      { Cell := Cell_1, cellFintype := cellFintype_1, Node := Node_1, nodeFintype := nodeFintype_1,
        cellForm := cellForm_1, cellNode := cellNode_1, parent := parent_1, rank := rank_1, eliminated := eliminated_1,
        front := front_1, root := root_1, globalForm := globalForm_1 } →
    Cell = Cell_1 ∧
      cellFintype ≍ cellFintype_1 ∧
        Node = Node_1 ∧
          nodeFintype ≍ nodeFintype_1 ∧
            cellForm ≍ cellForm_1 ∧
              cellNode ≍ cellNode_1 ∧
                parent ≍ parent_1 ∧
                  rank ≍ rank_1 ∧
                    eliminated ≍ eliminated_1 ∧ front ≍ front_1 ∧ root ≍ root_1 ∧ globalForm = globalForm_1

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {RD : Breakdown.CellCert.GivenModel.RowData M N}
  {Sp : Breakdown.CellCert.Assembly.CellSplit k N} {K₂ : Fin Sp.cellCount}
  {r : Breakdown.CellCert.CellSystem.CellEntry M N k Sp.slots}
  {C : Breakdown.CellCert.CellCoordinates.CellCoords k Sp.slots},
  Breakdown.CellCert.CellSystem.IsCellSystemFacts α c M MD RD Sp K₂ r C →
    Breakdown.CellCert.CellFormula.IsPressureLayout c r.box r.scalars r.bases C.layout

∀ {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {D : Breakdown.CellCert.GivenFields.ProfileData k}
  {A : Breakdown.CellCert.GivenFields.AuxData k} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {RD : Breakdown.CellCert.GivenModel.RowData M N} {X : Breakdown.CellCert.CellSystem.CellSystemData k N M},
  Breakdown.CellCert.CellSystem.IsReducedLosses c D A M RD X →
    ∀ j ∈ c.activeSet, ∀ p ∈ Breakdown.SteadyCert.box c.radius, √(X.adjointKernel j) / √c.weightMin ≤ c.adjointQuad j p

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {RD : Breakdown.CellCert.GivenModel.RowData M N}
  {Sp : Breakdown.CellCert.Assembly.CellSplit k N} {K₂ : Fin Sp.cellCount}
  {r : Breakdown.CellCert.CellSystem.CellEntry M N k Sp.slots}
  {C : Breakdown.CellCert.CellCoordinates.CellCoords k Sp.slots},
  Breakdown.CellCert.CellSystem.IsCellSystemFacts α c M MD RD Sp K₂ r C →
    r.rows.multiplierMatrix = RD.mix * Breakdown.CellCert.CellSystem.testMultiplierOf c RD r * RD.mix.transpose

∀ {k N slots : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {RD : Breakdown.CellCert.GivenModel.RowData M N} {K₀ : Fin M.cellCount}
  {R : Breakdown.CellCert.CellAnalysis.CellRows N slots k},
  Breakdown.CellCert.GivenModel.IsRowsInstance c M RD K₀ R → ∀ a ∈ R.rowSet, R.rowModeOf a = ↑(RD.harmonic a)

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {RD : Breakdown.CellCert.GivenModel.RowData M N}
  {Sp : Breakdown.CellCert.Assembly.CellSplit k N} {K₂ : Fin Sp.cellCount}
  {r : Breakdown.CellCert.CellSystem.CellEntry M N k Sp.slots}
  {C : Breakdown.CellCert.CellCoordinates.CellCoords k Sp.slots},
  Breakdown.CellCert.CellSystem.IsCellSystemFacts α c M MD RD Sp K₂ r C →
    Breakdown.CellCert.Reduction.IsGivenBases r.box r.baseDegree r.givenBases

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {W : Breakdown.CellCert.Reduction.WeightData},
  Breakdown.CellCert.Reduction.IsWeightTests α c K S W → S.weightFloor ≤ W.symAt K S 0 0 (↑(W.J + 1) * ↑c.order) true

∀ {k N slots : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {RD : Breakdown.CellCert.GivenModel.RowData M N} {K₀ : Fin M.cellCount}
  {R : Breakdown.CellCert.CellAnalysis.CellRows N slots k},
  Breakdown.CellCert.GivenModel.IsRowsInstance c M RD K₀ R → c.row = RD.rowField c.order

∀ {N slots k : ℕ} {yModes rowModes : Finset ℤ} {rowSet : Finset (Fin N)} {farShare : ℝ}
  {multiplierMatrix : Matrix (Fin N) (Fin N) ℝ} {reducerCount : ℕ} {reducer : Matrix (Fin reducerCount) (Fin N) ℝ}
  {farSupport : Finset (ℤ × Fin 3 × Fin 4 × ℕ × ℕ)}
  {farKernel : ℤ × Fin 3 × Fin 4 × ℕ × ℕ ⊕ Fin k ⊕ Fin k → ℤ × Fin 3 × Fin 4 × ℕ × ℕ ⊕ Fin k ⊕ Fin k → ℂ}
  {classRowWeight : Fin N → ℝ} {rowModeOf : Fin N → ℤ} {yModes_1 rowModes_1 : Finset ℤ} {rowSet_1 : Finset (Fin N)}
  {farShare_1 : ℝ} {multiplierMatrix_1 : Matrix (Fin N) (Fin N) ℝ} {reducerCount_1 : ℕ}
  {reducer_1 : Matrix (Fin reducerCount_1) (Fin N) ℝ} {farSupport_1 : Finset (ℤ × Fin 3 × Fin 4 × ℕ × ℕ)}
  {farKernel_1 : ℤ × Fin 3 × Fin 4 × ℕ × ℕ ⊕ Fin k ⊕ Fin k → ℤ × Fin 3 × Fin 4 × ℕ × ℕ ⊕ Fin k ⊕ Fin k → ℂ}
  {classRowWeight_1 : Fin N → ℝ} {rowModeOf_1 : Fin N → ℤ},
  { yModes := yModes, rowModes := rowModes, rowSet := rowSet, farShare := farShare,
        multiplierMatrix := multiplierMatrix, reducerCount := reducerCount, reducer := reducer,
        farSupport := farSupport, farKernel := farKernel, classRowWeight := classRowWeight, rowModeOf := rowModeOf } =
      { yModes := yModes_1, rowModes := rowModes_1, rowSet := rowSet_1, farShare := farShare_1,
        multiplierMatrix := multiplierMatrix_1, reducerCount := reducerCount_1, reducer := reducer_1,
        farSupport := farSupport_1, farKernel := farKernel_1, classRowWeight := classRowWeight_1,
        rowModeOf := rowModeOf_1 } →
    yModes = yModes_1 ∧
      rowModes = rowModes_1 ∧
        rowSet = rowSet_1 ∧
          farShare = farShare_1 ∧
            multiplierMatrix = multiplierMatrix_1 ∧
              reducerCount = reducerCount_1 ∧
                reducer ≍ reducer_1 ∧
                  farSupport = farSupport_1 ∧
                    farKernel = farKernel_1 ∧ classRowWeight = classRowWeight_1 ∧ rowModeOf = rowModeOf_1

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {RD : Breakdown.CellCert.GivenModel.RowData M N}
  {Sp : Breakdown.CellCert.Assembly.CellSplit k N} {K₂ : Fin Sp.cellCount}
  {r : Breakdown.CellCert.CellSystem.CellEntry M N k Sp.slots}
  {C : Breakdown.CellCert.CellCoordinates.CellCoords k Sp.slots},
  Breakdown.CellCert.CellSystem.IsCellSystemFacts α c M MD RD Sp K₂ r C → r.scalars.strainBound = fun x => r.strainConst

∀ {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {D : Breakdown.CellCert.GivenFields.ProfileData k}
  {A : Breakdown.CellCert.GivenFields.AuxData k} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {RD : Breakdown.CellCert.GivenModel.RowData M N} {X : Breakdown.CellCert.CellSystem.CellSystemData k N M},
  Breakdown.CellCert.CellSystem.IsReducedLosses c D A M RD X →
    ∀ (a : Fin X.curlSums.boxCount), X.curlSums.boxBound a ≤ X.curlKernel

∀ {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {D : Breakdown.CellCert.GivenFields.ProfileData k}
  {A : Breakdown.CellCert.GivenFields.AuxData k} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {RD : Breakdown.CellCert.GivenModel.RowData M N} {X : Breakdown.CellCert.CellSystem.CellSystemData k N M},
  Breakdown.CellCert.CellSystem.IsReducedLosses c D A M RD X →
    (2 * Real.pi) ^ (-1 / 2) * (27 / 256) ^ (1 / 4) * c.weightMin ^ (-3 / 4) ≤ c.productConst

∀ {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {B : Breakdown.CellCert.CellAnalysis.CellBases}
  {L : Breakdown.CellCert.CellFormula.CellLayout},
  Breakdown.CellCert.CellFormula.IsCellLayout c K S B L → L.degSide + 1 ≤ L.degCoef

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {RD : Breakdown.CellCert.GivenModel.RowData M N}
  {Sp : Breakdown.CellCert.Assembly.CellSplit k N} {K₂ : Fin Sp.cellCount}
  {r : Breakdown.CellCert.CellSystem.CellEntry M N k Sp.slots}
  {C : Breakdown.CellCert.CellCoordinates.CellCoords k Sp.slots},
  Breakdown.CellCert.CellSystem.IsCellSystemFacts α c M MD RD Sp K₂ r C →
    ∀ (j : Fin (Breakdown.CellCert.CellCoordinates.systemSkeletonCoords C.layout C.param).card) (i : Fin k),
      ∑ l, C.Tmap j l * Sp.freeMap l i = 0

∀ {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {B : Breakdown.CellCert.CellAnalysis.CellBases}
  {L : Breakdown.CellCert.CellFormula.CellLayout},
  Breakdown.CellCert.CellFormula.IsCellLayout c K S B L →
    ∀ (c : Fin L.cornerCount),
      (L.cornerOther c).1 = K.r₁ + K.r₂ - (L.corner c).1 ∧ (L.cornerOther c).2 = K.z₁ + K.z₂ - (L.corner c).2

∀ {α : ℝ} {k N : ℕ} {d : Breakdown.SteadyCert.FracCertData k N} {j : Fin k} {p : Fin k → ℝ}
  {D : Breakdown.CellCert.Reduction.AdjointDual k},
  Breakdown.CellCert.CellSystem.IsAdjointDualNumbers α d j p D → Breakdown.SteadyCert.l2Norm D.dualField ≤ D.dualBound

∀ {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {D : Breakdown.CellCert.GivenFields.ProfileData k}
  {A : Breakdown.CellCert.GivenFields.AuxData k} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {RD : Breakdown.CellCert.GivenModel.RowData M N} {X : Breakdown.CellCert.CellSystem.CellSystemData k N M},
  Breakdown.CellCert.CellSystem.IsSystemInstance c D A M RD X → Function.Bijective fun K₂ => (X.cell K₂).meshCell

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {RD : Breakdown.CellCert.GivenModel.RowData M N}
  {Sp : Breakdown.CellCert.Assembly.CellSplit k N} {K₂ : Fin Sp.cellCount}
  {r : Breakdown.CellCert.CellSystem.CellEntry M N k Sp.slots}
  {C : Breakdown.CellCert.CellCoordinates.CellCoords k Sp.slots},
  Breakdown.CellCert.CellSystem.IsCellSystemFacts α c M MD RD Sp K₂ r C →
    r.rows.reducer = Breakdown.CellCert.CellSystem.testReducerOf c RD r * RD.mix⁻¹

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {RD : Breakdown.CellCert.GivenModel.RowData M N}
  {Sp : Breakdown.CellCert.Assembly.CellSplit k N} {K₂ : Fin Sp.cellCount}
  {r : Breakdown.CellCert.CellSystem.CellEntry M N k Sp.slots}
  {C : Breakdown.CellCert.CellCoordinates.CellCoords k Sp.slots},
  Breakdown.CellCert.CellSystem.IsCellSystemFacts α c M MD RD Sp K₂ r C → r.scalars.meanGradBound = fun x => r.meanConst

∀ {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {W : Breakdown.CellCert.Reduction.WeightData}
  {F : Breakdown.CellCert.CellAnalysis.FarMajorantData},
  Breakdown.CellCert.Reduction.IsFarFloorTests c K S W F →
    F.strainFloor ≤
      W.energy * Breakdown.CellCert.CellAnalysis.CellScalars.tailLam K (S.degNear + 1) 0 - W.resolvedStrain - W.shift

∀ {k : ℕ} {left right : Breakdown.CellCert.Assembly.FieldTuple k → ℝ}
  {point : Breakdown.CellCert.Assembly.FieldTuple k → ℝ → ℝ}
  {left_1 right_1 : Breakdown.CellCert.Assembly.FieldTuple k → ℝ}
  {point_1 : Breakdown.CellCert.Assembly.FieldTuple k → ℝ → ℝ},
  { left := left, right := right, point := point } = { left := left_1, right := right_1, point := point_1 } →
    left = left_1 ∧ right = right_1 ∧ point = point_1

∀ {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {W : Breakdown.CellCert.Reduction.WeightData},
  Breakdown.CellCert.Reduction.IsWeightForm c K S W → ∀ (n : ℤ), S.tailShift n = if n ∈ S.resolved then W.shift else 0

∀ {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {D : Breakdown.CellCert.GivenFields.ProfileData k}
  {A : Breakdown.CellCert.GivenFields.AuxData k} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {R : Breakdown.CellCert.GivenModel.RowData M N},
  Breakdown.CellCert.GivenFields.IsGivenData c D A M MD R → Breakdown.CellCert.GivenModel.IsModelInstance c M MD

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {MD : Breakdown.CellCert.GivenModel.ModelData M k} {RD : Breakdown.CellCert.GivenModel.RowData M N}
  {Sp : Breakdown.CellCert.Assembly.CellSplit k N} {K₂ : Fin Sp.cellCount}
  {r : Breakdown.CellCert.CellSystem.CellEntry M N k Sp.slots}
  {C : Breakdown.CellCert.CellCoordinates.CellCoords k Sp.slots},
  Breakdown.CellCert.CellSystem.IsCellSystemFacts α c M MD RD Sp K₂ r C → RD.degree + MD.degree + 2 ≤ r.rowDegree

∀ {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {D : Breakdown.CellCert.GivenFields.ProfileData k}
  {A : Breakdown.CellCert.GivenFields.AuxData k} {M : Breakdown.CellCert.GivenModel.CellMesh}
  {RD : Breakdown.CellCert.GivenModel.RowData M N} {X : Breakdown.CellCert.CellSystem.CellSystemData k N M},
  Breakdown.CellCert.CellSystem.IsSystemInstance c D A M RD X →
    ∀ (K₂ : Fin X.split.cellCount), (X.mesh.coords K₂).gaugeLeft = X.mesh.canonicalLeft K₂

∀ {K : Breakdown.CellCert.CellAnalysis.CellBox} {B : Breakdown.CellCert.CellAnalysis.CellBases} {D : ℕ} {I O : Type}
  [inst : Fintype I] [inst_1 : Fintype O] {T : Breakdown.CellCert.CellAnalysis.TailFamily I O},
  Breakdown.CellCert.Reduction.IsTailColumnBound K B D T → ∀ (i : I) (l : ℕ), 0 ≤ T.heightBound i l

