  {indices_1 : Finset (Fin k → ℕ)} {coef_1 : (Fin k → ℕ) → Breakdown.CellCert.GivenFields.FieldData},
  { indices := indices, coef := coef } = { indices := indices_1, coef := coef_1 } → indices = indices_1 ∧ coef = coef_1

