  {boxZHi : Fin boxCount → Option ℝ} {rule : Fin boxCount → Fin pieceCount → Bool → Fin 3}
  {sectorLength : Fin boxCount → Fin pieceCount → Bool → ℝ} {boxBound : Fin boxCount → ℝ} {pieceCount_1 : ℕ}
  {pieceRhoLo_1 : Fin pieceCount_1 → ℝ} {pieceRhoHi_1 : Fin pieceCount_1 → Option ℝ} {pieceZLo_1 : Fin pieceCount_1 → ℝ}
