  {rule_1 : Fin boxCount_1 → Fin pieceCount_1 → Bool → Fin 3}
  {sectorLength_1 : Fin boxCount_1 → Fin pieceCount_1 → Bool → ℝ} {boxBound_1 : Fin boxCount_1 → ℝ},
  { pieceCount := pieceCount, pieceRhoLo := pieceRhoLo, pieceRhoHi := pieceRhoHi, pieceZLo := pieceZLo,
        pieceZHi := pieceZHi, pieceSolid := pieceSolid, pieceSup := pieceSup, pieceMass := pieceMass,
        boxCount := boxCount, boxRhoLo := boxRhoLo, boxRhoHi := boxRhoHi, boxZLo := boxZLo, boxZHi := boxZHi,
        rule := rule, sectorLength := sectorLength, boxBound := boxBound } =
      { pieceCount := pieceCount_1, pieceRhoLo := pieceRhoLo_1, pieceRhoHi := pieceRhoHi_1, pieceZLo := pieceZLo_1,
        pieceZHi := pieceZHi_1, pieceSolid := pieceSolid_1, pieceSup := pieceSup_1, pieceMass := pieceMass_1,
        boxCount := boxCount_1, boxRhoLo := boxRhoLo_1, boxRhoHi := boxRhoHi_1, boxZLo := boxZLo_1, boxZHi := boxZHi_1,
